-- Fase 2.4: estructura preparada; NO APLICAR sin autorización PostgreSQL.
CREATE TYPE "TableStatus" AS ENUM ('AVAILABLE','OCCUPIED','CLEANING','RESERVED','BLOCKED','OUT_OF_SERVICE');
CREATE TYPE "TableSessionStatus" AS ENUM ('OPEN','CLOSED');
CREATE TABLE "areas" ("id" UUID NOT NULL,"organization_id" UUID NOT NULL,"branch_id" UUID NOT NULL,"code" VARCHAR(64) NOT NULL,"display_name" VARCHAR(160) NOT NULL,"status" "LifecycleStatus" NOT NULL DEFAULT 'ACTIVE',"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "areas_pkey" PRIMARY KEY("id"));
CREATE TABLE "dining_tables" ("id" UUID NOT NULL,"organization_id" UUID NOT NULL,"branch_id" UUID NOT NULL,"area_id" UUID NOT NULL,"code" VARCHAR(64) NOT NULL,"capacity" INTEGER NOT NULL,"status" "TableStatus" NOT NULL DEFAULT 'AVAILABLE',"device_id" UUID,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "dining_tables_pkey" PRIMARY KEY("id"),CONSTRAINT "dining_tables_capacity_check" CHECK ("capacity" > 0));
CREATE TABLE "table_sessions" ("id" UUID NOT NULL,"organization_id" UUID NOT NULL,"branch_id" UUID NOT NULL,"table_id" UUID NOT NULL,"opened_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"closed_at" TIMESTAMPTZ(6),"status" "TableSessionStatus" NOT NULL DEFAULT 'OPEN',"version" INTEGER NOT NULL DEFAULT 1,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "table_sessions_pkey" PRIMARY KEY("id"),CONSTRAINT "table_sessions_version_check" CHECK ("version" > 0),CONSTRAINT "table_sessions_closed_check" CHECK (("status" = 'OPEN' AND "closed_at" IS NULL) OR ("status" = 'CLOSED' AND "closed_at" IS NOT NULL)));
CREATE UNIQUE INDEX "areas_organization_id_branch_id_code_key" ON "areas"("organization_id","branch_id","code"); CREATE UNIQUE INDEX "areas_id_organization_id_branch_id_key" ON "areas"("id","organization_id","branch_id"); CREATE INDEX "areas_organization_id_branch_id_status_idx" ON "areas"("organization_id","branch_id","status");
CREATE UNIQUE INDEX "dining_tables_organization_id_branch_id_code_key" ON "dining_tables"("organization_id","branch_id","code"); CREATE UNIQUE INDEX "dining_tables_id_organization_id_branch_id_key" ON "dining_tables"("id","organization_id","branch_id"); CREATE INDEX "dining_tables_organization_id_branch_id_status_idx" ON "dining_tables"("organization_id","branch_id","status"); CREATE INDEX "dining_tables_area_id_idx" ON "dining_tables"("area_id");
CREATE INDEX "table_sessions_organization_id_branch_id_table_id_status_idx" ON "table_sessions"("organization_id","branch_id","table_id","status"); CREATE UNIQUE INDEX "table_sessions_one_open_per_table" ON "table_sessions"("table_id") WHERE "status" = 'OPEN';
ALTER TABLE "areas" ADD CONSTRAINT "areas_organization_id_fkey" FOREIGN KEY("organization_id") REFERENCES "organizations"("id") ON DELETE RESTRICT; ALTER TABLE "areas" ADD CONSTRAINT "areas_branch_scope_fkey" FOREIGN KEY("branch_id","organization_id") REFERENCES "branches"("id","organization_id") ON DELETE RESTRICT; ALTER TABLE "dining_tables" ADD CONSTRAINT "dining_tables_organization_id_fkey" FOREIGN KEY("organization_id") REFERENCES "organizations"("id") ON DELETE RESTRICT; ALTER TABLE "dining_tables" ADD CONSTRAINT "dining_tables_branch_scope_fkey" FOREIGN KEY("branch_id","organization_id") REFERENCES "branches"("id","organization_id") ON DELETE RESTRICT; ALTER TABLE "dining_tables" ADD CONSTRAINT "dining_tables_area_scope_fkey" FOREIGN KEY("area_id","organization_id","branch_id") REFERENCES "areas"("id","organization_id","branch_id") ON DELETE RESTRICT; ALTER TABLE "table_sessions" ADD CONSTRAINT "table_sessions_organization_id_fkey" FOREIGN KEY("organization_id") REFERENCES "organizations"("id") ON DELETE RESTRICT; ALTER TABLE "table_sessions" ADD CONSTRAINT "table_sessions_branch_scope_fkey" FOREIGN KEY("branch_id","organization_id") REFERENCES "branches"("id","organization_id") ON DELETE RESTRICT; ALTER TABLE "table_sessions" ADD CONSTRAINT "table_sessions_table_scope_fkey" FOREIGN KEY("table_id","organization_id","branch_id") REFERENCES "dining_tables"("id","organization_id","branch_id") ON DELETE RESTRICT;
